/* Перевод опыта со старой линейной кривой (350 × (1 + 0.1 × (ур − 1))) на кривую v2: уровень и доля прогресса внутри уровня сохраняются. */
function legacyXpToV2(v) {
  let x = Math.max(0, Math.round(+v) || 0), l = 1;
  const need = function (n) { return Math.round(350 * (1 + 0.1 * (n - 1))); };
  while (l < B.XPC.cap && x >= need(l)) { x -= need(l); l++; }
  if (l >= B.XPC.cap) return B.xpAt(B.XPC.cap);
  return B.xpAt(l) + Math.floor(x / need(l) * B.xpNeed(l));
}
function cleanHxp(h) {
  if (h && h.hxp && typeof h.hxp === 'object' && h.xpCurve !== 2) { const v = {}; Object.keys(h.hxp).forEach(function (k) { v[k] = isFinite(+h.hxp[k]) ? legacyXpToV2(h.hxp[k]) : h.hxp[k]; }); h = Object.assign({}, h, { hxp: v }); }
